import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.CZxGLIO_.js";const u=JSON.parse('{"title":"关于 LeanCodeBox","description":"了解 LeanCodeBox 精简、内聚、低依赖的软件理念。","frontmatter":{"title":"关于 LeanCodeBox","description":"了解 LeanCodeBox 精简、内聚、低依赖的软件理念。"},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),n={name:"about/index.md"};function i(d,e,l,s,c,_){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="关于-leancodebox" tabindex="-1">关于 LeanCodeBox <a class="header-anchor" href="#关于-leancodebox" aria-label="Permalink to &quot;关于 LeanCodeBox&quot;">​</a></h1><p>LeanCodeBox 是一个专注于精简、干净、低依赖软件的 GitHub 组织。我们希望每个项目功能内聚、边界清晰，既容易理解和部署，也能在长期迭代中保持简单。</p><h2 id="我们重视什么" tabindex="-1">我们重视什么 <a class="header-anchor" href="#我们重视什么" aria-label="Permalink to &quot;我们重视什么&quot;">​</a></h2><ul><li>保留解决真实问题所需的能力，避免无谓复杂。</li><li>让功能和数据围绕清晰的项目边界保持内聚。</li><li>谨慎选择稳定依赖，减少不必要的运行时和外部服务。</li><li>把部署、升级、文档和长期维护视为软件本身的一部分。</li></ul><p>当前项目包括社区平台 <a href="./../docs/gooseforum/">GooseForum</a> 和任务调度工具 <a href="./../docs/rooster/">Rooster</a>。</p>',5)])])}const p=o(n,[["render",i]]);export{u as __pageData,p as default};
